      add(head, torus(0.2, 0.03, 10, 30), M.get('white'), [H.c.x, H.c.y - 0.255, H.c.z], [PI / 2, 0, 0]);
      add(head, torus(0.2, 0.008, 6, 30), glow, [H.c.x, H.c.y - 0.23, H.c.z], [PI / 2, 0, 0], null, { noShadow: true });
