    sweater: { drape: 0.8, kind: 3, neck: 0.078, sleeve: 0.97, cuff: 0.045, band: 0.045, hem: hip - 0.045, thick: 0.013, smooth: 60, arm: sleeve(1.16, 1.8), form: 0 },
