    jacket: { drape: 0.9, kind: 7, neck: 0.09, open: 0.046, vee: 0.17, sleeve: 0.97, cuff: 0.03, hem: hip - 0.075, thick: 0.014, smooth: 60, arm: sleeve(1.22, 1.85), form: 0 },
